SELECT * FROM (SELECT CASE WHEN balance >= 70000 THEN 'high' WHEN balance >= 14000 THEN 'mid' ELSE 'low' END AS balance_bucket, ROUND((100 * SUM(CASE WHEN status = 'OPEN' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_open FROM accounts WHERE status = 'OPEN' GROUP BY CASE WHEN balance >= 70000 THEN 'high' WHEN balance >= 14000 THEN 'mid' ELSE 'low' END) AS t WHERE pct_open >= 78 ORDER BY 2 DESC, balance_bucket;
